/**
     * The time frame when an automatic bill should be sent leave empty for no automated billing
     * <br><br>
     *
     * Example `"monthly"`
     * @example "monthly"
     */
    @IsEnum(ValidBillingCycles)
    @IsOptional()
    @ApiProperty({ enum: ValidBillingCycles, default: ValidBillingCycles.monthly })
    public billingCycle?: ValidBillingCycles;

    /**
     * The top-up amount for prepaid credit top-up billing cycle.
     * Required when billingCycle is 'topUp'. Only numerical string is allowed.
     * <br><br>Example: `"100.00"` for $100.00.
     * @example "100.00"
     */
    @IsNumberString()
    @IsOptional()
    @Validate(IsNumericStringGreaterThanOrEqualToZeroValidator)
    public topUpAmount?: string;

    /**
     * The threshold (as a fraction of topUpAmount) at which a top-up is triggered.
     * Optional, defaults to "0.2" (20%). Only numerical string between 0 and 1 is allowed.
     * <br><br>Example: `"0.2"` for 20%.
     * @example "0.2"
     */
    @IsNumberString()
    @IsOptional()
    @Validate(IsNumericStringGreaterThanOrEqualToZeroValidator)
    public topUpThreshold?: string;

