topup_class = '''
export class TopUpOffering extends UsageBased {
    static readonly logger = new Logger(TopUpOffering.name);
    public topUpAmount: string;
    public topUpThreshold: string;

    async topUp({ customer }: { customer: ReadCustomerResponseData }): Promise<void> {
        const creditService = this.customerService.creditService;
        if (!creditService) {
            TopUpOffering.logger.warn('CreditService not available for topUp');
            return;
        }

        // Get current wallet balance
        const balanceResult = await creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: customer.customerId,
        });
        const currentBalance = parseFloat(balanceResult.balance);

        const topUpAmount = parseFloat(this.topUpAmount);
        const threshold = parseFloat(this.topUpThreshold || '0.2');
        const thresholdAmount = topUpAmount * threshold;

        TopUpOffering.logger.log(
            \`TopUp check for customer \${customer.customerId}: balance=\${currentBalance}, threshold=\${thresholdAmount}, topUpAmount=\${topUpAmount}\`
        );

        // Treat balance exactly at threshold as sufficient
        if (currentBalance >= thresholdAmount) {
            TopUpOffering.logger.log(\`Balance \${currentBalance} >= threshold \${thresholdAmount}, no top-up needed\`);
            return;
        }

        // Calculate the gap to top up to
        const gap = topUpAmount - currentBalance;

        TopUpOffering.logger.log(\`Creating top-up invoice for \${gap} for customer \${customer.customerId}\`);

        // Create invoice with storePaymentAsCredit: true
        const lineItems = new (require('./invoice.entity.js').InvoiceLineItems)();
        lineItems.addLineItem(
            new (require('./invoice.entity.js').InvoiceLineItem)(
                \`\${this.offeringName} - Top Up\`,
                1,
                gap
            )
        );

        const { invoiceId } = await this.invoicesService.create({
            businessID: this.businessID,
            customerId: customer.customerId,
            customer,
            items: lineItems,
            invoiceDate: new Date().toISOString(),
            currency: Offering.getCurrency({ customer, offering: this }),
        }, false);

        TopUpOffering.logger.log(\`Top-up invoice \${invoiceId} created for customer \${customer.customerId}\`);
    }

    async processHourlyUsage({ customer }: { customer: ReadCustomerResponseData }): Promise<void> {
        const creditService = this.customerService.creditService;
        if (!creditService) {
            TopUpOffering.logger.warn('CreditService not available for hourly usage processing');
            return;
        }

        // Get current balance
        const balanceResult = await creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: customer.customerId,
        });
        let currentBalance = parseFloat(balanceResult.balance);

        // Calculate usage for the last hour
        const endDate = new Date();
        const startDate = new Date(endDate.getTime() - 60 * 60 * 1000);

        const lineItems = new (require('./invoice.entity.js').InvoiceLineItems)();
        await Offering.getLineItemsForUsage({
            startDate,
            endDate,
            customer,
            lineItems,
            negative: false,
            businessID: this.businessID,
            customerId: customer.customerId,
            customerService: this.customerService,
            offeringInstance: this,
            dimensions: this.dimensions,
        });

        const totalUsage = lineItems.getTotal();

        if (totalUsage > 0) {
            // Deduct usage as a negative credit transaction
            await creditService.create({
                transactionAmount: -totalUsage,
                businessID: this.businessID,
                customerId: customer.customerId,
                metadata: {
                    reason: \`Hourly usage deduction for \${this.offeringName}\`,
                    offeringId: this.offeringId,
                },
                timestamp: new Date().toISOString(),
            }, false);

            currentBalance -= totalUsage;
            TopUpOffering.logger.log(\`Deducted \${totalUsage} from customer \${customer.customerId} wallet, new balance: \${currentBalance}\`);
        } else {
            TopUpOffering.logger.log(\`Zero usage for customer \${customer.customerId}, no credit transaction created\`);
        }

        // Evaluate top-up with updated balance
        await this.topUp({ customer });
    }

    constructor({
        offeringName,
        customerId,
        invoicesService,
        schedulerService,
        dimensions,
        businessID,
        customerService,
        freeTrialLength,
        freeTrialEndDate,
        billingCycle,
        currency,
        settings,
        minimumCharge,
        usageOverrides,
        dimensionOverrides,
        offeringId,
        topUpAmount,
        topUpThreshold,
    }: {
        offeringName: string;
        businessID: string;
        customerId: string;
        invoicesService: InvoicesService;
        schedulerService?: SchedulerService;
        customerService?: CustomerService;
        dimensions: ReadOfferingResponseData['dimensions'];
        freeTrialLength?: string;
        freeTrialEndDate?: string;
        billingCycle?: ValidBillingCycles;
        currency?: SupportedCurrencies;
        settings: ReadSettingsResponseData;
        minimumCharge?: string;
        usageOverrides?: AggregatedUsageResponse[];
        dimensionOverrides?: DimensionOverridesDto[];
        offeringId: string;
        topUpAmount: string;
        topUpThreshold?: string;
    }) {
        super({
            offeringName,
            customerId,
            invoicesService,
            schedulerService,
            dimensions,
            businessID,
            customerService,
            freeTrialLength,
            freeTrialEndDate,
            billingCycle,
            currency,
            settings,
